export function FloatingValueCloud({props,style,context}:MotionComponentRenderPropsV1<FloatingValueCloudProps,ApprovedCh1Style>){const graph=useMotionGraphPresentation(),s=designScale(context),values=lines(props.values,14),shape=shapeFor(context),width=shape==='landscape'?'72%':shape==='balanced'?'74%':'78%',height=shape==='landscape'?'74%':'68%';return <div data-motion-root="floating-value-cloud" data-motion-node-id="component.root" style={{position:'absolute',inset:0,overflow:'hidden',display:'grid',placeItems:'center'}}>{backgroundLayer(graph,style)}<div data-motion-node-id="values.root" data-semantic-id="values.root" style={rootStyle('values.root',graph,context,style,{width,height,position:'relative',margin:0})}>{values.map((text,i)=>{const id=`values.item:${i}`,pos=VALUE_POSITIONS[i%VALUE_POSITIONS.length]!,q=itemQ(context,i,values.length,style,.02,.74),dx=context.reducedMotion?0:lerp(px(context,i%2?24:-24),0,q),dy=context.reducedMotion?0:lerp(px(context,i%3?18:-18),0,q),scale=context.reducedMotion?1:lerp(.88,1,easeOutBack(q,.55));let st=nodeStyle(graph,id,{position:'absolute',left:`${pos[0]}%`,top:`${pos[1]}%`,maxWidth:'42%',whiteSpace:'nowrap',padding:`${9*s}px ${13*s}px`,borderRadius:style.radius*1.6*s,background:rgba(style.surfaceColor,style.surfaceOpacity),color:'#e42b2b',fontWeight:style.fontWeight,fontSize:designClamp(context,14,5.5,28,style.typeScale),border:`${Math.max(2*s,style.borderWidth*s)}px solid color-mix(in srgb, ${style.borderColor} 35%, #e42b2b)`,boxShadow:`0 ${8*s}px ${20*s}px ${rgba('#000000',shadowAlpha(style)*.10/.18)}`,backdropFilter:`blur(${style.blur*s}px)`});if(!graph.scene)st={...st,opacity:q,transform:`translate3d(${dx}px,${dy}px,0) scale(${scale})`};return <div key={id} data-motion-node-id={id} data-semantic-id={id} style={st}>{text}</div>})}</div></div>}
