export interface CtaPillProps { readonly label:string; readonly subtext:string }
export const DEFAULT_CTA_PILL_PROPS:CtaPillProps=Object.freeze({label:'Follow',subtext:'for more'})
export const validateCtaPillProps=(input:unknown):MotionValidationResultV1<CtaPillProps>=>{if(!isRecord(input))return validationFailure(valueIssue('$','TYPE_INVALID','CTA Pill props must be an object.'));return validated(input as unknown as CtaPillProps,[textIssue('label',input.label,80),textIssue('subtext',input.subtext,120)].filter(Boolean) as any[])}
export const createCtaPillScene=(props:CtaPillProps,style:ApprovedCh1Style,context:MotionRenderContextV1):MotionSceneV1=>{const surface=graphShape({id:'cta.surface',name:'CTA Surface',parentId:'cta.root',width:px(context,220),height:px(context,90),fillColor:style.accentColor,strokeColor:style.borderColor,strokeWidth:px(context,style.borderWidth),radius:px(context,style.radius*1.6)}),label=graphText({id:'cta.label',name:'CTA Label',parentId:'cta.root',text:props.label,color:'#FFFFFF',fontFamily:style.fontFamily,fontSize:designClamp(context,30,13,76,style.typeScale),fontWeight:style.fontWeight,textAlign:'center'}),sub=graphText({id:'cta.subtext',name:'CTA Subtext',parentId:'cta.root',text:props.subtext,color:'#FFFFFF',fontFamily:style.fontFamily,fontSize:designClamp(context,12,2.7,20,style.typeScale),fontWeight:style.fontWeight,textAlign:'center'}),q=mBackOut(mEase('ease-out-cubic',mSequence(.02,.42,mProgress())),.48),nodes:Record<string,any>={};nodes['cta.surface']=Object.freeze({...surface,opacity:easeOutTrack('cta.surface.opacity',context,.02,.42,0,1),transform:Object.freeze({...surface.transform,scaleX:context.reducedMotion?constant(1):mNumber(mLerp(mConst(.86),mConst(1),q)),scaleY:context.reducedMotion?constant(1):mNumber(mLerp(mConst(.86),mConst(1),q))})});nodes['cta.label']=label;nodes['cta.subtext']=Object.freeze({...sub,opacity:easeOutTrack('cta.subtext.opacity',context,.34,.58,0,1),transform:Object.freeze({...sub.transform,positionY:context.reducedMotion?constant(0):easeOutTrack('cta.subtext.y',context,.34,.58,px(context,8),0)})});const ids=['cta.surface','cta.label','cta.subtext'];const exposures=[{id:'cta.label-text',label:'CTA label',group:'Content',level:'creator',target:{kind:'component',propertyId:'label'},editor:{type:'text'},keyframeable:false},{id:'cta.subtext-text',label:'Subtext',group:'Content',level:'creator',target:{kind:'component',propertyId:'subtext'},editor:{type:'text'},keyframeable:false},...commonExposures('cta','cta.root','cta.surface')] as MotionExposureV1[];return createShell('sanverse.cta-pill','CTA Pill','cta.root','CTA Pill',ids,nodes,[{id:'content',label:'CTA',role:'content-group',nodeIds:Object.freeze(ids)}],exposures,context,style)}
export function CtaPill({props,style,context}:MotionComponentRenderPropsV1<CtaPillProps,ApprovedCh1Style>){const graph=useMotionGraphPresentation(),s=designScale(context),p=normalizedProgress(context.localTicks,context.durationTicks),q=easeOutBack(easeOutCubic(sequenceProgress(p,.02,.42)),.48),subQ=easeOutCubic(sequenceProgress(p,.34,.58));let surface=nodeStyle(graph,'cta.surface',{padding:`${10*s}px ${22*s}px`,borderRadius:style.radius*1.6*s,background:`color-mix(in srgb, ${style.accentColor} 88%, transparent)`,color:'#fff',fontSize:designClamp(context,30,13,76,style.typeScale),lineHeight:1,fontWeight:style.fontWeight,letterSpacing:'-.05em',border:`${style.borderWidth*s}px solid ${style.borderColor}`,boxShadow:`0 ${12*s}px ${32*s}px ${rgba('#000000',shadowAlpha(style)*.16/.18)}`,backdropFilter:`blur(${style.blur*s}px)`}),sub=nodeStyle(graph,'cta.subtext',{padding:'.2em .42em',borderRadius:style.radius*.35*s,background:'#381014',color:'#fff',border:`${Math.max(1*s,style.borderWidth*s)}px solid ${style.borderColor||'#22080b'}`,fontWeight:style.fontWeight,fontSize:designClamp(context,12,2.7,20,style.typeScale),boxShadow:`0 ${3*s}px ${8*s}px ${rgba('#000000',shadowAlpha(style)*.16/.18)}`});if(!graph.scene){surface={...surface,opacity:q,transform:`scale(${lerp(.86,1,q)})`};sub={...sub,opacity:subQ,transform:`translate3d(0,${lerp(px(context,8),0,subQ)}px,0)`}}return <div data-motion-root="cta-pill" data-motion-node-id="component.root" style={{position:'absolute',inset:0,overflow:'hidden',display:'grid',placeItems:'center'}}>{backgroundLayer(graph,style)}<div data-motion-node-id="cta.root" data-semantic-id="cta.root" style={rootStyle('cta.root',graph,context,style,{display:'flex',flexDirection:'column',gap:px(context,8)})}><div data-motion-node-id="cta.surface" data-semantic-id="cta.surface" style={surface}><span data-motion-node-id="cta.label" data-semantic-id="cta.label">{props.label}</span></div><div data-motion-node-id="cta.subtext" data-semantic-id="cta.subtext" style={sub}>{props.subtext}</div></div></div>}
